const emptySteps='<div class="empty-state"><span>⌁</span><b>Waiting for execution</b><p>Intermediate values will appear here, one step at a time.</p></div>';
function updateKeyPreview(){const field=document.querySelector('#key'),preview=document.querySelector('#keyPreview');if(!field||!preview)return;const value=field.value.toUpperCase();let good=false,label='',mapping='';try{if(['monoalphabetic','substitution'].includes(current)){good=value.length===26&&new Set(value).size===26&&/^[A-Z]{26}$/.test(value);label=good?'VALID 26-LETTER PERMUTATION':'ENTER 26 UNIQUE A–Z LETTERS';mapping=value||'—';}else if(current==='playfair'){const sq=playfairSquare(value);good=true;label='VALID 5 × 5 KEY SQUARE';mapping=sq.join(' ');}else if(current==='hill'){const n=Number(document.querySelector('#matrixSize')?.value||2),mat=parseMatrix(value,n);inverseMatrix(mat);good=true;label=`INVERTIBLE ${n} × ${n} MATRIX`;mapping='['+mat.map(r=>r.join(' ')).join(']  [')+']';}else if(current==='polyalphabetic'){const shifts=value.split(/[ ,]+/).filter(Boolean).map(Number);good=shifts.length>0&&shifts.every(x=>Number.isInteger(x)&&x>=0&&x<26);label=good?'VALID REPEATING SHIFT KEY':'USE SHIFTS FROM 0 TO 25';mapping=shifts.join(', ');}else if(current==='vigenere'){good=/^[A-Z]+$/.test(value);label=good?'VALID VIGENÈRE KEY':'ENTER LETTERS A–Z ONLY';mapping=value;}}catch(_){good=false;label=current==='hill'?'MATRIX MUST BE INVERTIBLE MOD 26':'CHECK THE KEY FORMAT';}preview.innerHTML=`<div class="key-alphabet ${good?'valid':'invalid'}"><span>KEY CHECK</span><b>${good?'✓ ':'! '}${label}</b></div>`;const map=document.querySelector('#cipherAlphabet');if(map&&mapping)map.textContent=mapping;}
