function setFlowSteps(steps){document.querySelector('#runLabel').textContent='COMPLETE';flowUpdate();if(steps.length){document.querySelector('#flowDetail').innerHTML=`<span class="detail-marker">01</span><div><b>${steps[0].operation}</b><p>${escapeHtml(steps[0].calculation)}</p></div>`;}}
function bindFlow(){document.querySelector('#prevStep').onclick=()=>stepBy(-1);document.querySelector('#nextStep').onclick=()=>stepBy(1);document.querySelector('#playSteps').onclick=()=>{if(timer){clearInterval(timer);timer=null;document.querySelector('#playSteps').innerHTML='▷ &nbsp; Play steps';return}document.querySelector('#playSteps').innerHTML='Ⅱ &nbsp; Pause';timer=setInterval(()=>{if(runState.active>=runState.steps.length-1){clearInterval(timer);timer=null;document.querySelector('#playSteps').innerHTML='▷ &nbsp; Play steps';return}stepBy(1)},650)};document.querySelectorAll('.flow-node').forEach(n=>n.onclick=()=>{if(runState.steps.length){runState.active=Math.min(Number(n.dataset.step),runState.steps.length-1);flowUpdate()}})}
function stepBy(d){if(!runState.steps.length)return;runState.active=Math.max(0,Math.min(runState.steps.length-1,runState.active+d));flowUpdate()}
function flowUpdate(){const flowSteps=[...document.querySelectorAll('.flow-step')],active=runState.active;flowSteps.forEach(n=>{const index=Number(n.dataset.step);n.classList.toggle('active',index===active);n.classList.toggle('complete',index<active)});const edges=[...document.querySelectorAll('#flowchart .flow-edge i')];edges.forEach((n,i)=>n.classList.toggle('filled',i<=active));const s=runState.steps[active];if(s){document.querySelector('#flowDetail').innerHTML=`<span class="detail-marker">${String(active+1).padStart(2,'0')}</span><div><b>${escapeHtml(s.operation)}</b><p>${escapeHtml(s.calculation)} → ${escapeHtml(s.result)}</p></div>`;document.querySelector('#stepPosition').textContent=`${active+1} / ${runState.steps.length}`;document.querySelectorAll('.table-row').forEach((r,i)=>r.classList.toggle('selected',i===active));document.querySelector(`.flow-step[data-step="${active}"]`)?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'});}}
function updateCipherFlow(){const node=document.querySelectorAll('.flow-node')[1];if(node)node.querySelector('b').textContent=current==='modes'?`${document.querySelector('#mode')?.value.toUpperCase()||'CBC'} · ${document.querySelector('#cipherSelect')?.value.toUpperCase()||'AES'}`:'Algorithm rounds';const label=document.querySelector('#runLabel');if(label)label.textContent='READY';}
function resetFlowchart(){const f=document.querySelector('#flowchart');if(!f)return;f.classList.remove('cipher-flow');f.innerHTML='<div class="flow-node active" data-step="0"><span class="node-num">01</span><b>Input</b><small>Enter message</small></div><div class="flow-edge"><i></i></div><div class="flow-node" data-step="1"><span class="node-num">02</span><b>Algorithm rounds</b><small>Apply exact transform</small></div><div class="flow-edge"><i></i></div><div class="flow-node" data-step="2"><span class="node-num">03</span><b>Output</b><small>Review result</small></div>';updateCipherFlow();}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function copyText(text){if(!text||text==='—'){toast('Nothing to copy yet');return}navigator.clipboard?.writeText(text).then(()=>toast('Copied to clipboard')).catch(()=>toast('Clipboard is unavailable in this browser'))}
async function callCrypto(payload){if(location.protocol==='file:')throw Error('Open the URL printed by “npm start”; do not open the HTML file directly.');let response;try{response=await fetch('/api/crypto',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});}catch(_){throw Error('Could not reach the local crypto service. Start or restart the lab with “npm start”, then reload this page.');}const raw=await response.text();let data;try{data=JSON.parse(raw)}catch(_){throw Error(`Port ${location.port||'(default)'} is serving a different or stale app (HTTP ${response.status}). Stop old lab servers, run “npm start”, then open the exact URL printed in the terminal.`)}if(response.status===405)throw Error(data.error||'Wrong service is answering this request. Run “npm start” and open its printed URL.');if(!response.ok)throw Error(data.error||`Crypto request failed (${response.status}).`);return data}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
const theory={additive:'Each letter becomes a number A=0…Z=25. Add the key modulo 26; decryption subtracts the same key. This is the shift cipher family.',caesar:'The Caesar cipher is an additive cipher with a fixed shift. It preserves non-letter characters, but only has 26 possible keys and is not secure.',monoalphabetic:'Each plaintext letter is replaced by one fixed ciphertext letter. A one-to-one alphabet permutation makes decryption possible, but letter frequencies remain visible.',substitution:'General substitution uses a permutation of the alphabet. Additive and Caesar ciphers are special cases where the mapping is a simple rotation.',polyalphabetic:'A repeating sequence of shifts selects a different Caesar shift at each letter. The key period controls how the substitution changes through the message.',playfair:'Playfair encrypts digraphs using a 5×5 keyed square (I and J share a cell). Same-row, same-column and rectangle rules transform each pair. Filler X/Q characters can remain in decrypted text.',hill:'Hill cipher maps fixed-size letter vectors through a key matrix modulo 26. Decryption requires an invertible matrix whose determinant is coprime to 26. Encryption pads a final short block with X.',vigenere:'Vigenère is a classic polyalphabetic cipher. Each keyword letter supplies a shift; the keyword repeats over alphabetic characters.'};
const formula={additive:'C = (P + K) mod 26 &nbsp; · &nbsp; P = (C − K + 26) mod 26',caesar:'C = (P + K) mod 26 &nbsp; · &nbsp; K ∈ {0, …, 25}',monoalphabetic:'E(x) = π(x) &nbsp; · &nbsp; D(y) = π⁻¹(y)',substitution:'E(x) = key[x] &nbsp; · &nbsp; D(y) = key⁻¹[y]',polyalphabetic:'Cᵢ = (Pᵢ + Kᵢ) mod 26 &nbsp; · &nbsp; K repeats',playfair:'Two letters at a time · same row / column / rectangle rules',hill:'C = K·P mod 26 &nbsp; · &nbsp; P = K⁻¹·C mod 26',vigenere:'Cᵢ = (Pᵢ + Kᵢ) mod 26 &nbsp; · &nbsp; Pᵢ = (Cᵢ − Kᵢ) mod 26'};
const blockTheory={modes:'A mode defines how AES or DES processes multiple blocks. ECB transforms each independently; CBC chains with XOR; CFB and OFB use cipher feedback to create a keystream; CTR encrypts incrementing counter blocks. ECB reveals repeated blocks. CBC/CFB/OFB require an unpredictable or unique IV as applicable; CTR requires a unique counter for every key. This classroom tool checks IV byte length but cannot guarantee IV uniqueness.',des:'DES permutes a 64-bit block, splits it into L₀/R₀, then repeats Lᵢ=Rᵢ₋₁ and Rᵢ=Lᵢ₋₁ XOR F(Rᵢ₋₁,Kᵢ) for 16 rounds. F expands 32→48 bits, XORs the round key, applies eight S-boxes, then permutes; the halves swap before the final permutation. The effective key is 56 bits and obsolete for security.',aes:'AES is a standardized 128-bit block cipher with 128-, 192- or 256-bit keys. This lab runs Node’s OpenSSL AES primitive. AES-128 has 10 rounds, AES-192 has 12, and AES-256 has 14 (not 20). Each round uses its expanded round key: SubBytes, ShiftRows, MixColumns, AddRoundKey; the last round omits MixColumns. Decryption applies the inverse transformations in reverse key order. It is for education, not a production key-management system.', '2des':'2DES encryption is C=E(K₂,E(K₁,P)); decryption reverses it as D(K₁,D(K₂,C)). Each DES call performs its own 16 Feistel rounds. Two independent 56-bit keys do not provide 112-bit security because of meet-in-the-middle attacks.','3des':'3DES encryption is E(K₃,D(K₂,E(K₁,P))); decryption is D(K₁,E(K₂,D(K₃,C))). Every E or D stage runs 16 DES Feistel rounds with that stage’s key. Two-key 3DES sets K₃=K₁; three-key 3DES uses all three independent keys. It is legacy compatibility only.'};
function docsPage(){content.innerHTML=`<div class="page-heading"><div><div class="eyebrow">REFERENCE LIBRARY</div><div class="heading-title"><span class="heading-icon">▤</span><div><h1>Practical Documentation</h1><p>Experiment theory, algorithms and round-by-round calculations.</p></div></div></div></div><div class="docs-intro panel"><div class="banner-symbol">▤</div><div><div class="eyebrow">13 CRYPTOGRAPHY EXPERIMENTS</div><h2>Practical workspaces and reference notes.</h2><p>Open an experiment to run encryption and decryption, inspect mappings and read the algorithm notes. Use your browser’s print function to save or print the reference.</p></div><button class="button secondary" onclick="window.print()">Print this page <span>↗</span></button></div><div class="docs-list">${experiments.map((e,i)=>`<article class="doc-row"><span class="doc-num">${String(i+1).padStart(2,'0')}</span><div><b>${e.name}</b><small>${e.group} · ${e.difficulty}</small></div><span class="doc-status">${saved[e.id]?'✓ COMPLETED':'EXPERIMENT'}</span><button class="icon-button" data-page="${e.id}">↗</button></article>`).join('')}</div><div class="panel note-panel"><b>PDF / print</b><p>Use <kbd>Ctrl+P</kbd> / <kbd>⌘P</kbd> in your browser and choose “Save as PDF” to export this reference page.</p></div>`;content.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));}
