function aboutPage(){content.innerHTML=`<div class="page-heading"><div><div class="eyebrow">THE LAB</div><div class="heading-title"><span class="heading-icon">ⓘ</span><div><h1>About the Project</h1><p>A hands-on Computer Network Security laboratory for INFT students.</p></div></div></div></div><div class="about-hero panel"><div class="about-orbit">⌬</div><div class="eyebrow">VIDYALANKAR INSTITUTE OF TECHNOLOGY · DEPARTMENT OF INFT</div><h2>Learn the mechanics.<br><span>Build safer systems.</span></h2><p>This interactive lab presents cryptographic algorithms and controlled network-security practicals in one workspace. It is designed to pair the theory with observable, reversible learning exercises.</p></div><div class="team-grid"><section class="panel team-panel"><span class="panel-kicker">PROJECT TEAM</span><h2>Student contributors</h2><div class="team-row"><span class="avatar">IK</span><b>Iffat Khan</b><small>25101B2008</small></div><div class="team-row"><span class="avatar">GK</span><b>Gauri Khatokar</b><small>24101B0009</small></div><div class="team-row"><span class="avatar">SW</span><b>Simran Waghmare</b><small>25101B2009</small></div></section><section class="panel team-panel"><span class="panel-kicker">PROJECT MENTOR</span><h2>Faculty guidance</h2><div class="mentor-card"><span class="avatar mentor-avatar">VW</span><div><b>Vinita Bhandi Wad</b><small>Project Mentor</small></div></div><div class="about-callout">Academic laboratory project. Legacy ciphers are included for instruction and must not be used for real-world security.</div></section></div>`}
document.querySelector('#themeToggle').onclick=()=>{const html=document.documentElement;const next=html.dataset.theme==='dark'?'light':'dark';html.dataset.theme=next;localStorage.setItem('cns-theme',next);document.querySelector('#themeToggle').textContent=next==='dark'?'☼':'☾'};
nav.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});
